import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;
    static FastScanner fs;

    public static void main(String[] args) {
        fs = new FastScanner(System.in);
        int t = 1;
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < t; i++) {
            long res = solve();
            output.append(res).append('\n');
        }
        System.out.print(output);
    }

    static long solve() {
        int n = fs.nextInt();
        long m = fs.nextLong();

        boolean[] isPrime = getPrimes(n + 10);

        long pre = 1;
        long ans = 1;
        long ans1 = 1;
        long res = 0;

        for (int i = 2; i <= n; i++) {
            if (pre <= m && isPrime[i]) {
                pre *= i;
            }
            if (pre > m) {
                ans = 0;
            } else {
                ans = mul(ans, m / pre);
            }
            ans1 = mul(ans1, 1);
            res = mod(res + ans1 - ans);
        }
        return res;
    }

    static boolean[] getPrimes(int n) {
        boolean[] nums = new boolean[n + 1];
        Arrays.fill(nums, true);
        nums[0] = nums[1] = false;
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            if (nums[i]) primes.add(i);
            for (int j = 0; j < primes.size() && primes.get(j) <= n / i; j++) {
                nums[primes.get(j) * i] = false;
                if (i % primes.get(j) == 0) break;
            }
        }
        return nums;
    }

    static long mod(long num) {
        num %= MOD;
        if (num < 0) num += MOD;
        return num;
    }

    static long mul(long a, long b) {
        return (a * b) % MOD;
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

